# frozen_string_literal: true

require_relative '../../../step/buy_train'

module Engine
  module Game
    module G1846
      module Step
        class BuyTrain < Engine::Step::BuyTrain
          def actions(entity)
            return [] if entity.receivership?

            if entity == current_entity.owner
              return can_issue?(current_entity) ? [] : %w[sell_shares]
            end

            return [] unless entity.corporation?

            if must_buy_train?(entity)
              actions_ = %w[buy_train]
              actions_ << 'sell_shares' if can_issue?(entity)
              actions_
            elsif can_buy_train?(entity)
              %w[buy_train pass]
            else
              []
            end
          end

          def skip!
            @round.receivership_train_buy(self, :process_buy_train)
          end

          def issuable_shares(entity)
            return [] unless entity.corporation?

            @game.emergency_issuable_bundles(entity)
          end

          def process_sell_shares(action)
            return process_issue_shares(action) if action.entity.corporation?

            if can_issue?(@round.current_entity)
              raise GameError, 'President may not sell shares while corporation can issues shares.'
            end

            super
          end

          def can_issue?(entity)
            return false if @round.emergency_issued
            return false unless entity.corporation?
            return false unless issuable_shares(entity).any?

            true
          end

          def sellable_bundle?(bundle)
            # don't let President close the corporation that needs to buy a train
            # https://boardgamegeek.com/thread/2094996/article/30495803#30495803
            return false if (bundle.corporation == current_entity) &&
                            (bundle.corporation.share_price.price == 10)

            super
          end

          def process_issue_shares(action)
            corporation = action.entity
            bundle = action.bundle

            issuable = issuable_shares(corporation)
            bundle_index = issuable.index(bundle)

            if !can_issue?(corporation) || !bundle_index
              raise GameError, "#{corporation.name} cannot issue share bundle: #{bundle.shares}"
            end

            @last_share_issued_price = if bundle_index.zero?
                                         bundle.price
                                       else
                                         bundle.price - issuable[bundle_index - 1].price
                                       end

            @game.share_pool.sell_shares(bundle)

            old_price = corporation.share_price
            bundle.num_shares.times { @game.stock_market.move_left(corporation) }
            @game.log_share_price(corporation, old_price)

            @round.emergency_issued = true
          end

          def buyable_trains(entity)
            super.select do |train|
              next false if @last_share_issued_price && !train.from_depot?
              next false if train.owner.receivership?
              next false if @game.two_player? && @depot.empty? && train.owner.trains.one?

              true
            end
          end

          def buyable_train_variants(train, entity)
            variants = super

            return variants if (variants.size < 2) || train.owned_by_corporation?

            min, max = variants.sort_by { |v| v[:price] }
            pres_cash = president_may_contribute?(entity) ? entity.owner.cash : 0
            if ((min[:price] <= entity.cash + pres_cash) && (entity.cash + pres_cash < max[:price])) || entity.receivership?
              return [min]
            end

            # player is not allowed to sell shares and then buy a "weaker" train if the corp could already afford a weaker train
            if (last_cash_raised = @last_share_sold_price || @last_share_issued_price)
              must_spend = entity.cash - last_cash_raised + 1
              must_spend += entity.owner.cash if @last_share_sold_price

              variants.reject! { |v| v[:price] < must_spend }
            end

            variants
          end

          def buying_power(entity)
            @game.train_buying_power(entity)
          end

          def president_may_contribute?(corporation, _shell = nil)
            must_buy_train?(corporation) && ebuy_president_can_contribute?(corporation)
          end
        end
      end
    end
  end
end
